#!/usr/bin/env python3
"""Render the batch signal measurements into the human-readable reference report."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[2]
data=json.loads((root/'workspace/analysis/manus_12s/analysis.json').read_text())
notes=[
('Identity, promise, product entry','Opens on restrained black/white identity cards (“2.0”, “Introducing Manus 2.0”, “See”), then a black chapter index with blue selection against dim neighbors. A scenic waterfall image bridges the sparse type into a translucent product/results card. The exact point of each transition is not resolved by 1.5-second sampling.'),
('Feature cards, prompt surface, creative workspace','White cards (“Fewer tokens”, “Unlock more with Manus Studio”, “Create videos”) give way to a prompt surface and dark creative workspace. One statement or product proof at a time keeps hierarchy legible through the light-to-dark register change.'),
('Game-builder controls and playable output','Feature language moves into game-builder controls and a playable scene. Asset choices and edit-panel state changes show interaction rather than a static feature list. The useful grammar is choose → see result → adjust.'),
('Editable character and game proof','A fox-like character/editor demonstration makes the “edit every detail” claim tangible; white copy cards then introduce online multiplayer and game examples. UI-to-output alternation drives interest without requiring noisy glitch effects.'),
('Multiplayer and game-world variety','Lobby/racing imagery and different game worlds sit between clean white title cards. “Build any game / You Imagine” broadens the claim. Colorful output is contained by readable framing and punctuated by typographic resets.'),
('3D creation and desktop workflow','Game scenes yield to statements about 3D creation, Windows apps and hosted apps. The mostly white Manus Studio desktop and its configuration states move the viewer from promise toward concrete interface proof.'),
('Prompt entry and computer-use demonstration','The desktop setup advances into prompt entry, a vivid Windows desktop and an application. The sequence raises information density but remains spatially organized by screen and window framing. The sound window is measurably energetic; energy is not a subjective loudness claim.'),
('Demo preview and “Put it…” pause','Desktop preview and app use lead into the spare “Put it…” title pause, followed by Studio setup/computer use. Scale and framing shifts carry energy while a clean title reset gives the eye a brief breath.'),
('Computer-use chapter and device interaction','“Watch Manus use your computer” prepares phone/computer interaction, Xcode/app testing and desktop/device states. The sequence communicates action followed by inspection; title punctuation begins the next chapter turn.'),
('“One More Thing” and new identity reveal','Repeated “One More Thing” resolves into a black chapter card with electric-blue “New” and a highlighted menu item. A “Meet Cue!” pill begins the geometric agent-character reveal. This is a strong contrast pivot; NewEra should borrow only the abstract chapter-punctuation principle.'),
('Agent identity to named assistant','Geometric characters gather, followed by a scenic frame and a phone UI for a named Health Manager with connected assets. Identity spectacle resolves to a concrete device demonstration.'),
('Collaboration and call-forwarding setup','A title reset introduces agent collaboration. Selection/check states, group chat and differentiated agent messages demonstrate coordination; another white card introduces call forwarding. Product state—not a permanent HUD—explains the feature.'),
('QR entry, team utility and local-agent network','A dark QR statement contrasts with warm contextual imagery. A QR card becomes mascot/logo and enters a white UI; blue emphasis in “Saved to your team” clarifies roster state. “Later, from anywhere” and a completed pickup request expand utility toward a town/network of agents.'),
('User agency and quiet final hold','“Manus gives you the power to build” resolves through “You” into “You decide what’s worth building.” Characters frame a small mark before the wordmark settles. Composition decelerates rather than ending on a chaotic burst; exact easing and hold timing are not claimed.')]
lines=['# Manus 2.0 reference — 12-second visual/audio deconstruction','',f"**Source:** `{data['source']}` ({data['duration_sec']:.3f}s, 1920×1080, 30 fps). **Method:** {data['method']}",'','This adds a finer-grained, measured companion to `../manus_analysis.md`. The MP4 is sampled every 1.5 s, up to eight thumbnails per 12 s window. It cannot prove exact edit boundaries, animation easing, instrument identity, or audio/visual sync. The observations describe only visible sampled frames; statements about scene flow are approximate where a window boundary crosses a transition. Audio flux candidates are not verified beats.','', '| Time (s) | Visual narrative / design observations | RMS | Low-band share* | Flux candidates | Thumbnail delta** | Sheet |','|---|---|---:|---:|---:|---:|---|']
for b,(title,desc) in zip(data['batches'],notes):
    bands=b['mean_band_power']; denom=sum(bands.values()) or 1; share=bands['low_20_120']/denom*100
    lines.append(f"| {b['start_sec']:.1f}–{b['end_sec']:.1f} | **{title}.** {desc} | {b['reference_audio_rms']:.3f} | {share:.1f}% | {len(b['spectral_flux_events_sec'])} | {b['sampled_frame_mean_abs_delta_0_1']:.3f} | `{b['contact_sheet']}` |")
maxb=max(data['batches'],key=lambda b:b['reference_audio_rms'])
lines += ['', '* The band share is relative to the three selected bands only (20–120, 250–2500, 4000–11025 Hz); it is not a proportion of perceptual loudness. The low-bitrate source and frequency-bin distribution affect this measure.', '** Mean absolute RGB pixel difference between successive 1.5-second thumbnails downscaled to 120×68. It is a reproducible coarse change indicator, not a cut detector: motion, color, transitions, framing, and UI changes all affect it.', '', '## Audio and editorial reading','',f"Reference-window RMS ranges {min(b['reference_audio_rms'] for b in data['batches']):.3f}–{max(b['reference_audio_rms'] for b in data['batches']):.3f}; the measured maximum is in {maxb['start_sec']:.1f}–{maxb['end_sec']:.1f}s. Spectral-flux novelty candidates range from {min(len(b['spectral_flux_events_sec']) for b in data['batches'])} to {max(len(b['spectral_flux_events_sec']) for b in data['batches'])} per window. The three-band mean-power comparison is strongly dominated by the low band throughout; this does not mean that the original music is perceived as bass-only. It is not a stem separation. The reference’s transferable editorial quality is contrast between clean typographic breaths and readable product proof; chapter changes vary framing and register without maintaining a permanently dense overlay. Use the separately analyzed Life Force beat map—not this unrelated reference soundtrack—for NewEra edit timing.",'', '## Limits and transfer to NewEra','',data['limitations'],'', 'The 14 contact sheets cover the full reference duration, with the final partial window. Sparse frames may miss brief cuts and text. Neither the image delta nor flux candidates establish cuts per minute/bar, exact transient-to-frame error, velocity/easing, perceived loudness, or precise musical events. NewEra takes only broad design principles: high-contrast chapter punctuation, one clear proof at a time, restrained accents, and a quieter resolved finish. No Manus footage, logos, copy, characters, or UI assets are used.','']
path=root/'workspace/analysis/manus_12s/README.md'
path.write_text('\n'.join(lines))
main=root/'workspace/manus_analysis.md'
with main.open('a') as f: f.write('\n\n## Fine-grained measured companion\n\nThe full 14-window, 12-second-per-batch analysis (sample contact sheets, per-window audio metrics, visual-difference caveats, and design observations) is documented in [`analysis/manus_12s/README.md`](analysis/manus_12s/README.md) and machine-readable `analysis/manus_12s/analysis.json`. The repeatable extractor is `analysis/analyze_manus_batches.py`. It covers the full 166.464-second reference; its measurements are explicitly not presented as exact cut/beat/sync ground truth.\n')
print('Wrote',path,'and linked from',main)
